return (() => {
  const body = document.body ? (document.body.innerText || '') : '';
  const detected = body.indexOf('already logged in') !== -1 ||
    body.indexOf('Already Logged In') !== -1 ||
    body.indexOf('already logged on') !== -1;
  if (!detected) { return 'no-interstitial'; }
  const links = document.querySelectorAll('a');
  for (let i = 0; i < links.length; i++) {
    const text = links[i].textContent.toLowerCase();
    if (text.indexOf('click here') !== -1 || text.indexOf('continue') !== -1 ||
        text.indexOf('log in') !== -1 || text.indexOf('login') !== -1) {
      links[i].click();
      return 'forced-new-session';
    }
  }
  throw new Error('already-logged-in page detected but no force-login link found');
})();

return (() => {
  const target = '${COMPANY_NAME}';
  const links = document.querySelectorAll('#CompanyList a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === target) { links[i].click(); return true; }
  }
  throw new Error('Company not found in list: ' + target);
})();

return (() => {
  const start = new Date('${START_DATE}' + 'T00:00:00');
  const end = new Date('${END_DATE}' + 'T00:00:00');
  if (isNaN(start.getTime()) || isNaN(end.getTime())) {
    throw new Error('Invalid START_DATE or END_DATE');
  }
  const fields = [
    ['StartMonth', String(start.getMonth() + 1)],
    ['StartDay', String(start.getDate())],
    ['StartYear', String(start.getFullYear())],
    ['EndMonth', String(end.getMonth() + 1)],
    ['EndDay', String(end.getDate())],
    ['EndYear', String(end.getFullYear())]
  ];
  let applied = 0;
  for (let i = 0; i < fields.length; i++) {
    const el = document.querySelector('select[name="' + fields[i][0] + '"]');
    if (el) {
      el.value = fields[i][1];
      el.dispatchEvent(new Event('change'));
      applied++;
    }
  }
  if (applied === 0) { throw new Error('No date select fields found'); }
  return applied;
})();

return (async () => {
  const link = document.querySelector("a[href*='/DownloadFile']");
