  const headerRow = 'Transaction Code,Division Name,First Name,Middle Initial,Last Name,Title,Social Security Number,Visa Number,Password,Date of Birth,Gender,Ethnic Code,Address,Address [continued],City,County,State,Postal Code,Country,Home Phone,Work Phone,Work Phone Ext.,Email,Alternative Email,Marital Status,Marital Date,Veteran Status,Date of Employment,Hours Worked Per Week,Annual Wages,Commission,Bonus,Reported Tips,Subject To Social Security,Subject To FUTA,Subject To Medicare,Subject To AEIC,Occupation,Job Description,Smoking Status,Supervisor ID,College1 Name,College1 Degree,College1 Year Graduated,College2 Name,College2 Degree,College2 Year Graduated,Emergency Contact1 First Name,Emergency Contact1 Last Name,Emergency Contact1 Address,Emergency Contact1 Apt,Emergency Contact1 City,Emergency Contact1 State,Emergency Contact1 Postal Code,Emergency Contact1 Home Phone,Emergency Contact1 Work Phone,Emergency Contact1 Work Phone Ext.,Emergency Contact1 Relationship,Emergency Contact1 Email,Emergency Contact2 First Name,Emergency Contact2 Last Name,Emergency Contact2 Address,Emergency Contact2 Apt,Emergency Contact2 City,Emergency Contact2 State,Emergency Contact2 Postal Code,Emergency Contact2 Home Phone,Emergency Contact2 Work Phone,Emergency Contact2 Work Phone Ext.,Emergency Contact2 Relationship,Emergency Contact2 Email,Doctors Name,Doctors Phone,Doctors Phone Ext.,Known Allergies,Payroll File Number,Final Payroll Date,Rate Type,Rate Per Hour,Time Off Remaining,Contribution Interval Override,Pay Frequency,Payroll Schedule Name,OT Multiplier,Federal Filing Status,Federal Exemptions,Federal Do Not Calculate,Federal Tax,Federal Allowances,Federal Withholding,Federal FUTA,Federal SSN Med Tax,Federal SSN,Federal Extra Tax Type,Federal Extra Tax Amount,State Worked In,State Lived In,State Filing Status,State Exemptions,State FUTA,State Do Not Calculate,State Tax,State SUI SDI Tax,State SUI SDI Taxable,State Extra Tax Type,State Extra Tax Amount,Subject To SUI,St