  const quote = function (f) {
    if (f.indexOf(',') === -1 && f.indexOf('"') === -1 &&
        f.indexOf('\n') === -1 && f.indexOf('\r') === -1) { return f; }
    return '"' + f.split('"').join('""') + '"';
  };
  const lines = raw.trim().split('\n');
  const rows = [];
