    let line = lines[i];
    if (line.charAt(line.length - 1) === '\r') { line = line.slice(0, -1); }
    if (!line) { continue; }
    const fields = line.split('\t');
    const out = [];
    for (let j = 0; j < fields.length; j++) {
      out.push(quote(fields[j] === '~' ? '' : fields[j]));
    }
    rows.push(out.join(','));
  }
  if (rows.length === 0) { throw new Error('Export contained no data rows'); }
  return headerRow + '\r\n' + rows.join('\r\n') + '\r\n';
})();
